-- Canonical prevention bundle baseline. These are static system templates, not user-created records.
-- Migration execution has no auth.uid(), while the shared management audit trigger requires one.
-- Disable user triggers only for this seed transaction; normal runtime trigger behavior is restored immediately after.
set local session_replication_role = replica;

insert into public.prevention_bundle_templates
(organization_id,bundle_key,name,title_el,title_en,version,status,scope,source,source_version,departments,elements,is_system,hidden,published_at)
select null,'CLABSI','CLABSI','Κεντρικός φλεβικός καθετήρας','Central venous catheter','1.0','published','CVC insertion / maintenance','WHO · CDC','reviewed 2026','["ΜΕΘ"]'::jsonb,
'[{"id":"necessity","labelEl":"Τεκμηριωμένη ένδειξη / καθημερινή ανάγκη για CVC","labelEn":"Documented indication / daily CVC necessity review","required":true},{"id":"hand_hygiene","labelEl":"Υγιεινή χεριών πριν από χειρισμό","labelEn":"Hand hygiene before manipulation","required":true},{"id":"aseptic","labelEl":"Άσηπτη τεχνική κατά την εισαγωγή / χειρισμό","labelEn":"Aseptic technique during insertion / manipulation","required":true},{"id":"barrier","labelEl":"Μέγιστες στείρες προφυλάξεις κατά την εισαγωγή","labelEn":"Maximal sterile barrier precautions during insertion","required":true},{"id":"skin","labelEl":"Κατάλληλη αντισηψία δέρματος και χρόνος στεγνώματος","labelEn":"Appropriate skin antisepsis and drying time","required":true},{"id":"site","labelEl":"Καθημερινή αξιολόγηση σημείου εισόδου","labelEn":"Daily insertion-site assessment","required":true},{"id":"hub","labelEl":"Απολύμανση συνδέσμου πριν από πρόσβαση","labelEn":"Hub disinfection before access","required":true},{"id":"dressing","labelEl":"Επίδεση καθαρή, στεγνή και ακέραιη","labelEn":"Dressing clean, dry and intact","required":true},{"id":"remove","labelEl":"Άμεση αφαίρεση όταν δεν είναι πλέον απαραίτητος","labelEn":"Prompt removal when no longer necessary","required":true}]'::jsonb,true,false,now()
where not exists (select 1 from public.prevention_bundle_templates where organization_id is null and bundle_key='CLABSI' and version='1.0');

