'[{"id":"antibiotic","labelEl":"Κατάλληλη χειρουργική αντιμικροβιακή προφύλαξη σύμφωνα με τοπικό πρωτόκολλο","labelEn":"Appropriate surgical antimicrobial prophylaxis per local protocol","required":true},{"id":"hair","labelEl":"Αποφυγή ξυρίσματος· κατάλληλη αποτρίχωση μόνο όταν απαιτείται","labelEn":"Avoid shaving; appropriate hair removal only when necessary","required":true},{"id":"skin","labelEl":"Κατάλληλη προεγχειρητική αντισηψία δέρματος","labelEn":"Appropriate preoperative skin antisepsis","required":true},{"id":"glucose","labelEl":"Περιεγχειρητικός γλυκαιμικός έλεγχος όπου ενδείκνυται","labelEn":"Perioperative glycemic control where indicated","required":false},{"id":"temperature","labelEl":"Διατήρηση νορμοθερμίας όπου ενδείκνυται","labelEn":"Maintain normothermia where indicated","required":false},{"id":"asepsis","labelEl":"Τήρηση άσηπτης τεχνικής / αποστειρωμένου πεδίου","labelEn":"Maintain aseptic technique / sterile field","required":true},{"id":"wound","labelEl":"Τεκμηριωμένη μετεγχειρητική φροντίδα τραύματος","labelEn":"Documented postoperative wound care","required":true}]'::jsonb,true,false,now()
