'[{"id":"hand_hygiene","labelEl":"Υγιεινή χεριών πριν και μετά τον χειρισμό της αγγειακής προσπέλασης","labelEn":"Hand hygiene before and after vascular-access manipulation","required":true},{"id":"aseptic","labelEl":"Άσηπτη τεχνική κατά σύνδεση, αποσύνδεση και χειρισμό καθετήρα","labelEn":"Aseptic technique during connection, disconnection and catheter handling","required":true},{"id":"hub","labelEl":"Κατάλληλη απολύμανση hub/συνδέσεων πριν από πρόσβαση","labelEn":"Appropriate hub/connection disinfection before access","required":true},{"id":"site","labelEl":"Αξιολόγηση σημείου προσπέλασης για σημεία λοίμωξης","labelEn":"Access-site assessment for signs of infection","required":true},{"id":"dressing","labelEl":"Κατάλληλη φροντίδα και ακεραιότητα επιδέσμου καθετήρα","labelEn":"Appropriate catheter dressing care and integrity","required":true},{"id":"medication","labelEl":"Άσηπτη προετοιμασία και χορήγηση ενέσιμων φαρμάκων","labelEn":"Aseptic preparation and administration of injectable medications","required":true},{"id":"cleaning","labelEl":"Καθαρισμός/απολύμανση σταθμού και εξοπλισμού μεταξύ ασθενών","labelEn":"Station and equipment cleaning/disinfection between patients","required":true},{"id":"surveillance","labelEl":"Έλεγχος για πρόσφατα συμβάντα λοίμωξης ή καλλιέργειες σχετιζόμενες με την προσπέλαση","labelEn":"Review for recent access-related infection events or cultures","required":false}]'::jsonb,true,false,now()
